CSS='''body{font:16px/1.7 "Malgun Gothic","Apple SD Gothic Neo",sans-serif;color:#203249;margin:0;background:#f4f7fb}main{max-width:1200px;margin:auto;background:white;padding:48px}h1{font-size:32px}h2{margin-top:46px;border-top:3px solid #2457a6;padding-top:20px}h3{color:#2457a6}table{border-collapse:collapse;width:100%;font-size:13px;margin:16px 0}th,td{border:1px solid #dce4ef;padding:8px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#edf3fc}code{font-size:13px;background:#edf2f8;padding:2px 4px;overflow-wrap:anywhere}.note{background:#eaf5f3;border-left:4px solid #148782;padding:16px}.cards{display:flex;gap:16px;flex-wrap:wrap}.card{background:#edf3fc;padding:18px;min-width:140px}.card b{display:block;font-size:28px}svg{width:100%;height:auto}a{color:#2457a6}.scroll{overflow:auto}details{margin:16px 0}summary{cursor:pointer;font-weight:bold}@media print{body{background:white}main{padding:0}table{font-size:10px}h2{break-before:page}tr{break-inside:avoid}}'''
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+E(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def page(name,title,body):
 p=R/'reports'/name;p.write_text('<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>'+E(title)+'</title><style>'+CSS+'</style><main><a href="index.html">전체 안내</a><h1>'+E(title)+'</h1>'+body+'</main></html>',encoding='utf-8')
def svg(nodes,edges,height):
 out=['<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1120 '+str(height)+'" role="img"><defs><marker id="arrow" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto"><path d="M0,0 L0,6 L9,3 z" fill="#647b96"/></marker></defs>']
 for a,b,label,dashed in edges:
  x,y,w,h,_=nodes[a];xx,yy,ww,hh,_=nodes[b];x1=x+w/2;y1=y+h;x2=xx+ww/2;y2=yy
  if yy==y:x1=x+w;y1=y+h/2;x2=xx;y2=yy+hh/2
  out.append(f'<path d="M{x1},{y1} L{x2},{y2}" stroke="#647b96" stroke-width="2" fill="none" marker-end="url(#arrow)" '+('stroke-dasharray="7 5"' if dashed else '')+'/>' )
  out.append(f'<text x="{(x1+x2)/2+8}" y="{(y1+y2)/2-8}" font-size="14" fill="#38506b">{E(label)}</text>')
 for x,y,w,h,lines in nodes.values():
  out.append(f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="9" fill="#edf3fc" stroke="#2457a6"/>')
  for i,line in enumerate(lines):out.append(f'<text x="{x+14}" y="{y+27+i*23}" font-family="NanumGothic,Malgun Gothic,sans-serif" font-size="{16 if i==0 else 13}" fill="#203249">{E(line)}</text>')
 return ''.join(out)+'</svg>'
