logical=svg({'emp':(20,20,290,90,['검수원','식별자: 사번','직원 1 : 검수 N']),'category':(760,20,340,90,['카테고리','식별자: 카테고리 코드','카테고리 1 : 검수 N']),'inspection':(330,220,420,105,['검수 최종 상태','식별자: 검수 ID','개정 번호·상품 코드·상위 참조·시각','하나의 ID에는 최종 유효 행 한 건']),'dict':(20,425,300,90,['표준 코드 사전','식별자: 사전 ID','조회 키: 코드 유형 + 표준 코드']),'view':(440,425,550,90,['검수 조회용 결합 데이터','식별자: 검수 ID + 개정 번호','검수 1 : 결합 데이터 1 / 이름·부서·배상금 재구성'])},[('emp','inspection','사번 참조',False),('category','inspection','상위 참조',False),('inspection','view','동일 검수·개정',False),('dict','view','상품 코드·결과 코드 대조',True)],550)
physical=svg({'emp':(20,20,345,92,['silver_inspector_master','PK EMP_NO','UNIQUE source_bronze_row_id']),'cat':(740,20,360,92,['silver_category_parent_lookup','PK CAT_ID','UNIQUE source_bronze_row_id']),'fact':(285,220,550,115,['silver_inspection','PK (INSP_ID, REV_NO) / UNIQUE INSP_ID','FK INSPECTOR_EMP_NO → EMP_NO','FK PARENT_CAT_ID → CAT_ID']),'joined':(285,430,550,92,['silver_inspection_join_ready','PK (INSP_ID, REV_NO) / UNIQUE INSP_ID','FK (INSP_ID, REV_NO) → silver_inspection'])},[('emp','fact','참조',False),('cat','fact','참조',False),('fact','joined','같은 최종 검수',False)],555)
